# Noise color is the one forming smallest/dispersed objects; remove those cells, then remove empty columns.
def f(g, noise):
    h, w = g.shape
    rows_out = [[v for v in row if v != noise] for row in g]
    # keep uniform width by taking max length across rows
    outp = [row + [g[0,0]]*(max(0, max(len(r) for r in rows_out)-len(row))) for row in rows_out]
    res = np.array(outp)
    while True:
        idx = None
        for j in range(res.shape[1]):
            if np.all(res[:,j]==res[0,0]):
                idx = j; break
        if idx is None: break
        res = np.delete(res, idx, axis=1)
    return res

# Demo candidates for noise: find color with fewest total cells among non-bg colors
def guess_noise(grid):
    bg = grid[0,0]
    counts = {}
    for val in set(grid.flatten()):
        if val != bg:
            counts[val] = int(np.sum(grid==val))
    return min(counts, key=counts.get)

for name,inp,outp in [("demo1",A,B),("demo2",C,D),("demo3",E,F)]:
    n = guess_noise(inp)
    pred = f(inp, n)
    print(name, "noise=",n, "match", np.array_equal(pred,outp))

