    bg = cnt.most_common(1)[0][0]
    # flood fill: components of non-bg plus noise; shift each component down so its lowest cell rests on the bottom or another component
    H,W = len(g), len(g[0])
    seen = set(); comps = []
    for r in range(H):
        for c in range(W):
            val = g[r][c]
            if val == bg or (r, c) in seen:
                continue
            comp = []; stack = [(r, c)]; seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc, g[rr][cc]))
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and g[nr][nc] != bg and (nr, nc) not in seen:
                        seen.add((nr, nc)); stack.append((nr, nc))
            comps.append(comp)
    res = [[bg]*W for _ in range(H)]
    # gravity down within each component: move each cell down as far as possible without overlapping other cells (including other parts of same component? no—only cells of same color? treat all together)
    # Instead: for each component, project cells down along column, stacking bottom-aligned within the bounding box.
    # Known interpretation: drop cells; they fall to bottom, landing on other dropped cells.
    drop_cells = {}  # col -> list of (cell_r, new_r)
    for comp in comps:
        for rr, cc, v in comp:
            drop_cells.setdefault(cc, []).append((rr, v))
    for col, cells in drop_cells.items():
        # sort by original r desc, fall into available slots from bottom
        sorted_cells = sorted(cells, key=lambda x: x[0], reverse=True)
        used = set(); new_r_by_old = {}
        for old_r, v in sorted_cells:
            for dr in range(old_r, -1, -1):
                if dr not in used:
                    new_r = dr
                    used.add(new_r)
                    break
            else:
                new_r = None
        if new_r_by_old.get(None) is not None:
            pass  # fallback? 
    return res

