def T(g, noise=None, gravity='none', compress=False):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    res=[row[:] for row in g]
    if noise is not None:
        for r in range(H):
