                if res[r][c]==noise:
                    res[r][c]=bg
    if gravity == 'down':
        for c in range(W):
            vals=[res[r][c] for r in range(H)]
            nb=[v for v in vals if v!=bg]
            npos=[i for i,v in enumerate(vals) if v!=bg]
            new=[bg]*H
            for i,(v,r) in enumerate(zip(nb,npos)):
                new[i]=v
            for i in range(H):
                res[c][i]=new[i]
    elif gravity == 'up':
        for c in range(W):
            vals=[res[r][c] for r in range(H)]
            nb=[v for v in vals if v!=bg]
            npos=[i for i,v in enumerate(vals) if v!=bg]
            new=[bg]*H
            for i,(v,r) in enumerate(zip(nb,npos)):
                new[H-1-i]=v
            for i in range(H):
                res[c][i]=new[i]
    if compress:
        col_has = any(row[c]!=bg for row in res)
        res=[r for r in zip(*[(row[c] for row in res) for c in range(W)]) if any(col_has[c] for _ in range(H))] # wrong
