# My loader reads grids as list of strings; transpose the whole grid.
def load_transposed():
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        out=[[0]*k for _ in range(w)]
        for r,row in enumerate(t[m.end():].split('\n')[:h]):
            vals=[int(v) for v in row.split()]
            for c,v in enumerate(vals):
                out[c][r]=v
        G[k]=out
    return G

